INSERT INTO `ticket_news` VALUES (1, '关于系统维护的公告', '为了提供更好的服务，系统将于2025年12月25日0:00-6:00进行维护，期间可能无法正常访问。给您带来的不便，敬请谅解！', 1, '', '2025-12-20 08:34:50.823865', '2025-12-20 08:34:50.823906');
INSERT INTO `ticket_news` VALUES (2, '旅游旺季购票须知', '尊敬的用户，旅游旺季即将到来，为了确保您的购票体验，建议您提前7天预订门票。同时，请您仔细阅读购票须知，合理安排行程。', 1, '', '2025-12-20 08:34:50.828803', '2025-12-20 08:34:50.828834');
INSERT INTO `ticket_news` VALUES (4, '2026年春节旅游攻略', '2026年春节即将到来，小编为您整理了一份春节旅游攻略。无论是热门景区还是小众景点，都能让您度过一个愉快的春节假期。', 0, '', '2025-12-20 08:34:50.837500', '2025-12-20 08:34:50.837530');
INSERT INTO `ticket_news` VALUES (5, '冬季热门旅游目的地推荐', '冬季旅游去哪里？小编为您推荐几个热门目的地：哈尔滨冰雪大世界、三亚亚龙湾、长白山天池、云南大理等。', 0, '', '2025-12-20 08:34:50.840595', '2025-12-20 08:34:50.840617');
INSERT INTO `ticket_news` VALUES (6, '如何选择适合自己的旅游线路', '选择旅游线路需要考虑多个因素：时间、预算、兴趣爱好、交通方式等。本文将为您详细介绍如何选择适合自己的旅游线路。', 0, '', '2025-12-20 08:34:50.844067', '2025-12-20 08:34:50.844110');
INSERT INTO `ticket_news` VALUES (7, '旅游安全注意事项', '旅游安全是重中之重，本文将为您介绍旅游过程中的安全注意事项，包括交通安全、食品安全、财物安全等。', 0, '', '2025-12-20 08:34:50.851646', '2025-12-20 08:34:50.851679');
INSERT INTO `ticket_news` VALUES (8, '景区门票预订指南', '预订景区门票有多种方式，本文将为您详细介绍如何通过我们的平台预订门票，以及预订过程中的注意事项。', 0, '', '2025-12-20 08:34:50.862940', '2025-12-20 08:34:50.862991');
INSERT INTO `ticket_news` VALUES (9, '旅游保险购买攻略', '旅游保险是旅游过程中的重要保障，本文将为您介绍旅游保险的种类、购买渠道、注意事项等。', 0, '', '2025-12-20 08:34:50.868874', '2025-12-20 08:34:50.868911');
INSERT INTO `ticket_news` VALUES (11, '亲子旅游推荐', '带孩子旅游是一种很好的亲子活动，本文将为您推荐几个适合亲子旅游的目的地和景点。', 0, '', '2025-12-20 08:34:50.875082', '2025-12-20 08:34:50.875109');
INSERT INTO `ticket_news` VALUES (12, '老年人旅游注意事项', '老年人旅游需要特别注意健康和安全，本文将为您介绍老年人旅游的注意事项和建议。', 0, '', '2025-12-20 08:34:50.878046', '2025-12-20 08:34:50.878077');
INSERT INTO `ticket_news` VALUES (13, '摄影爱好者必去的旅游目的地', '本文将为摄影爱好者推荐几个适合摄影的旅游目的地，包括自然风光、人文景观等。', 0, '', '2025-12-20 08:34:50.880896', '2025-12-20 08:34:50.880916');
INSERT INTO `ticket_news` VALUES (14, '美食旅游攻略', '旅游除了看风景，品尝当地美食也是重要的一部分。本文将为您推荐几个美食旅游目的地和特色美食。', 0, '', '2025-12-20 08:34:50.883586', '2025-12-20 08:34:50.883613');
INSERT INTO `ticket_news` VALUES (32, '2026年五一假期旅游市场预测：国内游需求将持续增长', '随着国内旅游市场的持续复苏，2026年五一假期的旅游需求预计将创下新高。据旅游部门预测，今年五一假期全国旅游人次有望突破2亿，同比增长超过20%。热门目的地包括北京、上海、广州、成都等一线城市，以及三亚、丽江、桂林等传统旅游胜地。为了应对即将到来的旅游高峰，各地旅游部门已提前制定了应急预案，加强景区管理，确保游客安全。同时，许多景区也推出了各种优惠活动，吸引更多游客前来参观。业内专家表示，随着旅游消费的不断升级，游客对高品质、个性化旅游产品的需求将持续增长，旅游企业应不断创新，提供更加优质的服务。', 0, '', '2026-03-04 03:56:33.545664', '2026-03-04 03:56:33.545686');
INSERT INTO `ticket_news` VALUES (33, '2026年中国旅游日主题确定：文旅融合，美好生活', '近日，文化和旅游部宣布，2026年中国旅游日的主题为\"文旅融合，美好生活\"。今年的中国旅游日将于5月19日举行，全国各地将开展丰富多彩的旅游推广活动。文化和旅游部表示，今年的主题旨在强调文化与旅游的深度融合，通过旅游体验丰富人们的精神文化生活，提升生活品质。活动期间，全国多家景区将推出门票优惠、文化展演等活动，吸引更多游客参与。此外，文化和旅游部还将组织开展\"文化旅游进社区\"、\"旅游志愿者服务\"等活动，进一步普及旅游知识，推广文明旅游理念。业内人士表示，文旅融合是旅游业发展的必然趋势，通过文化与旅游的结合，可以为游客提供更加丰富、深度的旅游体验。', 0, '', '2026-03-04 03:56:33.547796', '2026-03-04 03:56:33.547814');
INSERT INTO `ticket_news` VALUES (34, '2026年全球旅游趋势报告：可持续旅游成为新热点', '近日，世界旅游组织发布了《2026年全球旅游趋势报告》，报告显示，可持续旅游已成为全球旅游发展的新热点。越来越多的游客开始关注旅游对环境的影响，选择环保、低碳的旅游方式。报告指出，2025年全球可持续旅游市场规模已达到1.2万亿美元，预计2026年将增长15%以上。在可持续旅游的推动下，生态旅游、文化旅游、乡村旅游等形式逐渐成为主流。此外，报告还指出，数字化技术在旅游业中的应用越来越广泛，虚拟现实、人工智能等技术为游客提供了更加丰富的旅游体验。业内专家表示，可持续旅游不仅是旅游业发展的趋势，也是人类社会可持续发展的重要组成部分，旅游企业应积极采取措施，减少旅游活动对环境的影响，推动旅游业的绿色发展。', 0, '', '2026-03-04 03:56:33.549785', '2026-03-04 03:56:33.549800');
INSERT INTO `ticket_news` VALUES (35, '2026年中国十大热门旅游城市出炉', '近日，某旅游平台发布了《2026年中国十大热门旅游城市》榜单，北京、上海、成都、杭州、西安、重庆、广州、厦门、三亚、丽江入选。榜单基于平台大数据分析，综合考虑了游客数量、旅游收入、游客满意度等因素。北京以其丰富的历史文化遗产和现代化的城市景观位居榜首，上海则以其国际化的都市魅力和丰富的商业文化排名第二。成都凭借其独特的美食文化和悠闲的生活方式排名第三。此外，杭州的西湖、西安的兵马俑、重庆的山城风光、广州的岭南文化、厦门的海滨风情、三亚的热带风光、丽江的纳西族文化也吸引了大量游客。业内人士表示，随着旅游消费的不断升级，游客对旅游目的地的文化内涵和个性化体验要求越来越高，各城市应结合自身特色，打造独特的旅游品牌。', 0, '', '2026-03-04 03:56:33.551522', '2026-03-04 03:56:33.551536');
INSERT INTO `ticket_news` VALUES (36, '2026年旅游安全提示：出行前请注意这些事项', '随着旅游旺季的到来，旅游安全问题再次成为关注焦点。近日，文化和旅游部发布了2026年旅游安全提示，提醒广大游客在出行前注意以下事项：一、提前了解目的地的天气、交通、医疗等信息，做好充分准备；二、选择正规的旅行社和旅游产品，签订详细的旅游合同；三、注意个人财物安全，妥善保管身份证、护照等重要证件；四、遵守目的地的法律法规和风俗习惯，尊重当地文化；五、注意饮食卫生，避免食用生冷食物；六、购买旅游保险，保障自身权益。此外，文化和旅游部还提醒游客，在遇到突发情况时，要保持冷静，及时联系当地警方或中国驻外使领馆寻求帮助。业内专家表示，旅游安全是旅游业发展的基础，游客应增强安全意识，提高自我保护能力，共同营造安全、有序的旅游环境。', 0, '', '2026-03-04 03:56:33.553305', '2026-03-04 03:56:33.553322');
INSERT INTO `ticket_news` VALUES (37, '关于2026年清明假期景区开放时间调整的公告', '为了做好2026年清明假期的旅游接待工作，确保游客安全和游览体验，现将各景区开放时间调整如下：一、4月4日至4月6日（清明假期）期间，所有景区开放时间调整为8:00-18:00，比平时延长1小时；二、重点景区将实行分时预约制度，游客需提前通过官方网站或APP预约游览时间；三、景区将增加临时停车场和志愿者服务点，为游客提供便利；四、清明假期期间，景区将加强安全检查和环境保洁，确保景区环境整洁有序。请广大游客合理安排行程，错峰出行，文明旅游。如有疑问，请拨打景区咨询电话：400-123-4567。', 1, '', '2026-03-04 03:56:33.555201', '2026-03-04 03:56:33.555217');
INSERT INTO `ticket_news` VALUES (38, '关于开展2026年旅游服务质量提升行动的通知', '为了进一步提升旅游服务质量，满足游客日益增长的高品质旅游需求，文化和旅游部决定开展2026年旅游服务质量提升行动。本次行动将重点关注以下几个方面：一、加强旅游从业人员培训，提高服务意识和专业技能；二、规范旅游市场秩序，打击不合理低价游、强制消费等违法行为；三、推进旅游标准化建设，建立健全旅游服务质量评价体系；四、加强旅游投诉处理，提高游客满意度；五、推动智慧旅游发展，提升旅游服务的智能化水平。本次行动将持续一年，通过明察暗访、专项检查等方式，对旅游企业和景区的服务质量进行全面评估。对表现优秀的企业和景区，将给予表彰和奖励；对服务质量差的企业和景区，将依法依规进行处理。请各旅游企业和景区积极参与本次行动，共同提升旅游服务质量，为游客提供更加优质的旅游体验。', 1, '', '2026-03-04 03:56:33.557079', '2026-03-04 03:56:33.557094');
INSERT INTO `ticket_news` VALUES (39, '关于2026年五一假期旅游交通提示', '2026年五一假期即将到来，预计将出现旅游出行高峰。为了确保游客出行安全顺畅，交通运输部门发布了以下交通提示：一、五一假期（4月30日至5月4日）期间，全国高速公路将对7座及以下小型客车实行免费通行政策；二、预计4月29日下午和4月30日上午将出现出城高峰，5月4日下午将出现返程高峰，请游客合理安排出行时间，错峰出行；三、出行前请关注天气和路况信息，避免在恶劣天气条件下出行；四、遵守交通规则，文明驾驶，避免疲劳驾驶和酒后驾驶；五、在景区周边 parking时，请服从现场管理人员指挥，有序停车。此外，交通运输部门还将增加重点旅游线路的运力，确保游客出行需求。请广大游客提前规划行程，合理安排交通方式，确保假期出行安全顺畅。', 1, '', '2026-03-04 03:56:33.559407', '2026-03-04 03:56:33.559433');
INSERT INTO `ticket_news` VALUES (40, '关于加强2026年暑期旅游市场监管的通知', '为了规范暑期旅游市场秩序，保障游客合法权益，文化和旅游部决定加强2026年暑期旅游市场监管。本次监管行动将重点关注以下几个方面：一、打击不合理低价游、强制消费、虚假宣传等违法行为；二、加强景区门票价格监管，严禁哄抬票价；三、规范旅游包车市场，确保游客交通安全；四、加强旅游餐饮和住宿卫生监管，保障游客饮食和住宿安全；五、畅通旅游投诉渠道，及时处理游客投诉。文化和旅游部将联合市场监管、交通运输、公安等部门，开展联合执法检查，对违法违规行为依法依规进行处理。请广大游客在暑期旅游过程中，注意保留相关证据，如遇到违法违规行为，及时向当地文化和旅游部门投诉。同时，也请游客文明旅游，遵守景区规定，共同营造良好的旅游环境。', 1, '', '2026-03-04 03:56:33.562209', '2026-03-04 03:56:33.562230');
INSERT INTO `ticket_news` VALUES (41, '关于2026年国庆节景区预约游览的公告', '为了做好2026年国庆节期间的旅游接待工作，确保游客安全和游览体验，现将景区预约游览相关事项公告如下：一、2026年国庆节期间（10月1日至10月7日），全国重点景区将实行分时预约制度，游客需提前通过官方网站或APP预约游览时间；二、预约时间从9月20日开始，游客可提前10天预约；三、每个身份证每天只能预约一个景区的门票；四、预约成功后，游客需凭身份证和预约码进入景区；五、景区将根据承载能力，合理控制每日游客数量，超过承载能力的日期将停止预约。请广大游客提前规划行程，及时预约，错峰出行。如有疑问，请拨打景区咨询电话：400-123-4567。', 1, '', '2026-03-04 03:56:33.564445', '2026-03-04 03:56:33.564465');
